"""
Mixed Chinese Postman Problem (MCPP) for mixed_chinese_postman_003.
20 stations, 35 segments. Same algorithm as mixed_chinese_postman_002.
"""
import json
import sys
import heapq
from ortools.sat.python import cp_model
from collections import defaultdict

def solve():
    segments = [
        [0,  1,  8, 3, 0],
        [1,  2,  6, 2, 0],
        [2,  3,  7, 4, 1],
        [3,  4,  5, 1, 0],
        [4,  5,  9, 2, 1],
        [5,  6,  4, 3, 0],
        [6,  7,  8, 5, 1],
        [7,  8,  6, 2, 0],
        [8,  9,  7, 3, 1],
        [9,  10, 5, 2, 0],
        [10, 11, 8, 4, 1],
        [11, 12, 4, 1, 0],
        [12, 13, 6, 3, 1],
        [13, 14, 7, 2, 0],
        [14, 15, 9, 4, 1],
        [15, 16, 5, 2, 0],
        [16, 17, 8, 3, 1],
        [17, 18, 6, 2, 0],
        [18, 19, 7, 4, 1],
        [19,  0,10, 5, 0],
        [1,   5, 8, 3, 0],
        [3,   7, 6, 2, 0],
        [5,   9, 7, 4, 1],
        [7,  11, 5, 1, 0],
        [9,  13, 8, 3, 1],
        [11, 15, 6, 2, 0],
        [13, 17, 7, 4, 1],
        [15, 19, 9, 5, 0],
        [17,  0, 5, 2, 1],
        [19,  2, 8, 3, 0],
        [2,   6, 6, 4, 1],
        [4,   8, 7, 2, 0],
        [6,  10, 5, 3, 0],
        [8,  12, 8, 5, 1],
        [10, 14, 6, 2, 0],
    ]

    N = 20

    INF = 10**9
    travel = [[INF]*N for _ in range(N)]
    for i in range(N):
        travel[i][i] = 0
    for u, v, m, t, bidi in segments:
        travel[u][v] = min(travel[u][v], t)
        if bidi:
            travel[v][u] = min(travel[v][u], t)
        else:
            travel[v][u] = min(travel[v][u], t)
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if travel[i][k] + travel[k][j] < travel[i][j]:
                    travel[i][j] = travel[i][k] + travel[k][j]

    def sp_path(src, dst):
        dist = [INF]*N; prev = [-1]*N; dist[src] = 0
        pq = [(0, src)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]: continue
            if u == dst: break
            for v in range(N):
                t = travel[u][v]
                if t < INF and dist[u]+t < dist[v]:
                    dist[v] = dist[u]+t; prev[v] = u
                    heapq.heappush(pq, (dist[v], v))
        path = []; cur = dst
        while cur != -1: path.append(cur); cur = prev[cur]
        return list(reversed(path))

    model = cp_model.CpModel()
    dir_vars = {}
    for i, (u, v, m, t, bidi) in enumerate(segments):
        if bidi:
            dir_vars[i] = model.NewBoolVar(f'd_{i}')

    imbalance = [model.NewIntVar(-35, 35, f'imb_{n}') for n in range(N)]
    for n in range(N):
        terms_const = 0
        terms_var = []
        for i, (u, v, m, t, bidi) in enumerate(segments):
            if not bidi:
                if u == n: terms_const += 1
                if v == n: terms_const -= 1
            else:
                dv = dir_vars[i]
                if u == n: terms_var.append(1 - 2*dv)
                if v == n: terms_var.append(2*dv - 1)
        model.Add(imbalance[n] == terms_const + sum(terms_var))

    abs_imb = [model.NewIntVar(0, 35, f'ai_{n}') for n in range(N)]
    for n in range(N): model.AddAbsEquality(abs_imb[n], imbalance[n])
    model.Minimize(sum(abs_imb))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 60
    solver.parameters.num_search_workers = 4
    status = solver.Solve(model)
    print(f"[DEBUG] CP-SAT status: {solver.StatusName(status)}", file=sys.stderr)

    directed_edges = []
    for i, (u, v, m, t, bidi) in enumerate(segments):
        if not bidi:
            directed_edges.append((u, v, m, t, i))
        else:
            if status in (cp_model.OPTIMAL, cp_model.FEASIBLE) and solver.Value(dir_vars[i]) == 1:
                directed_edges.append((v, u, m, t, i))
            else:
                directed_edges.append((u, v, m, t, i))

    out_deg = {n: 0 for n in range(N)}
    in_deg  = {n: 0 for n in range(N)}
    for u, v, m, t, si in directed_edges:
        out_deg[u] += 1; in_deg[v] += 1

    positive = []
    negative = []
    for n in range(N):
        imb = out_deg[n] - in_deg[n]
        if imb > 0: positive.extend([n]*imb)
        elif imb < 0: negative.extend([n]*(-imb))

    print(f"[DEBUG] pos={set(positive)}, neg={set(negative)}", file=sys.stderr)

    deadhead_paths = []
    rem_neg = list(negative); rem_pos = list(positive)
    while rem_neg and rem_pos:
        best = (INF, None, None)
        for ni, n in enumerate(rem_neg):
            for pi, p in enumerate(rem_pos):
                c = travel[n][p]
                if c < best[0]: best = (c, ni, pi)
        _, ni, pi = best
        n = rem_neg.pop(ni); p = rem_pos.pop(pi)
        deadhead_paths.append(sp_path(n, p))

    adj_list = defaultdict(list)
    for u, v, m, t, si in directed_edges:
        adj_list[u].append((v, m+t, si))
    for path in deadhead_paths:
        for k in range(len(path)-1):
            u, v = path[k], path[k+1]
            adj_list[u].append((v, travel[u][v], -1))

    adj_idx = {n: 0 for n in range(N)}
    stack = [0]; circuit = []
    while stack:
        v = stack[-1]
        if adj_idx[v] < len(adj_list[v]):
            nxt, cost, si = adj_list[v][adj_idx[v]]
            adj_idx[v] += 1; stack.append(nxt)
        else:
            circuit.append(stack.pop())
    route = list(reversed(circuit))

    seg_cleared = set()
    total_time = 0
    for k in range(len(route)-1):
        u, v = route[k], route[k+1]
        found = False
        for eu, ev, em, et, esi in directed_edges:
            if eu==u and ev==v and esi not in seg_cleared:
                total_time += em+et; seg_cleared.add(esi); found = True; break
        if not found:
            total_time += travel[u][v]

    print(json.dumps({"route": route, "total_time": total_time}))

if __name__ == '__main__':
    solve()
